command:
// Emblem RPG runs this migration automatically when the hosting GM loads a world saved by an older version.
// Run it by hand if that automatic migration failed, or after enabling a module whose compendiums were built for an
// older version: the automatic run happens once per world, so it never sees a module enabled later.

if (!game.user.isGM) return ui.notifications.warn('Migrate World Content is GM-only.');

const unattended = scope.automatic === true;
const proceed = unattended || await foundry.applications.api.DialogV2.confirm({
  window: { title: 'Migrate World Content' },
  classes: ['emblem-rpg', 'dialog-editor'],
  content: '<div class="ed-container"><div class="ed-section">'
    + '<p class="ed-description" style="font-size:13px; font-style:normal;">'
    + 'Brings your world content and module compendiums up to date with the system schema changes.</p></div></div>',
  rejectClose: false
});
if (!proceed) return;

const STUDIO = 'emblem-rpg-studio';
const OLD_CONDITION = 'Using: Specific Ability';
const NEW_CONDITION = 'Using Ability';
const DELETE = () => new foundry.data.operators.ForcedDeletion();
const VARIANT_SLOTS = ['armored', 'cavalry', 'armoredCavalry', 'flying'];
const { ForcedReplacement } = foundry.data.operators;
const DEAD_ITEM_FLAGS = ['emblem-rpg.animV2', 'emblem-rpg.autoRally', 'emblem-rpg-content.recoveredFrom', 'core.sourceId'];
const summary = {
  actors: 0, items: 0, customStatuses: 0, removeStatuses: 0, restoreActions: 0, ambiguous: [], conflicts: [], errors: []
};
// The item updates that also rewrite a custom status, counted in summary.customStatuses once their batch is written.
const customRewrites = new WeakSet();
// The item updates that also rewrite a Remove status step, counted in summary.removeStatuses once their batch is
// written. Each maps to the steps in it that kept their status name and dropped a dispel box.
const removeRewrites = new WeakMap();
// Remove status steps that kept their status name and dropped a dispel box, listed in the end notice.
const ambiguousSteps = [];
// The item updates that also rewrite a Restore actions step, counted in summary.restoreActions once their batch is
// written.
const restoreRewrites = new WeakSet();
// The Studio helpers the composition keys need. A world without the Studio keeps its keys as they are, so the macro
// can be run again after enabling it.
const studio = game.modules.get(STUDIO)?.active !== true ? null : await Promise.all([
  'actor-art-files.mjs', 'character/model/art-destinations.mjs', 'character/model/composition-keys.mjs'
].map(file => import(foundry.utils.getRoute('modules/' + STUDIO + '/module/' + file))))
  .then(([files, destinations, keys]) => ({
    slugifyName: files.slugifyName, typeOptions: destinations.typeOptions, compKey: keys.compKey
  }))
  .catch(error => {
    summary.errors.push('Studio: composition keys were left as they are because its code could not be loaded. '
      + error.message);
    return null;
  });
const customStatus = await import(foundry.utils.getRoute('systems/emblem-rpg/module/contracts/dsl/custom-status.mjs'))
  .catch(error => {
    summary.errors.push('Custom statuses: they were left as they are because the system code that updates them '
      + 'could not be loaded. ' + error.message);
    return null;
  });
const removeStatus = await import(foundry.utils.getRoute('systems/emblem-rpg/module/contracts/dsl/remove-status.mjs'))
  .catch(error => {
    summary.errors.push('Remove status steps: they were left as they are because the system code that updates them '
      + 'could not be loaded. ' + error.message);
    return null;
  });
const restoreAction = await import(foundry.utils.getRoute('systems/emblem-rpg/module/contracts/dsl/restore-action.mjs'))
  .catch(error => {
    summary.errors.push('Restore actions steps: they were left as they are because the system code that updates them '
      + 'could not be loaded. ' + error.message);
    return null;
  });

/** Run one part of the migration, recording a failure instead of letting it stop the rest. */
async function guarded(label, work) {
  try {
    await work();
  } catch (error) {
    summary.errors.push(label + ': ' + (error?.message ?? error));
  }
}

/** Item write options. emblemUsesClamp stops the uses clamp, which reads a whole-block rewrite as a new maximum. */
function itemWriteOptions(pack = null) {
  return { ...(pack ? { pack } : {}), diff: false, render: false, emblemUsesClamp: true };
}

/** Rename the old condition, give name-only entries their trigger, and give every entry a unique ID. */
function planTabs(tabs) {
  let changed = 0;
  const next = tabs.map(tab => {
    if (!Array.isArray(tab?.entries)) return tab;
    const reserved = new Set(tab.entries.map(entry => entry?.id).filter(Boolean));
    const used = new Set();
    const entries = tab.entries.map(entry => {
      const out = { ...entry };
      let touched = false;
      for (const key of ['triggers', 'guards']) {
        if (Array.isArray(out[key]) && out[key].includes(OLD_CONDITION)) {
          out[key] = out[key].map(name => name === OLD_CONDITION ? NEW_CONDITION : name);
          touched = true;
        }
      }
      if (typeof out.name === 'string' && out.name.includes(OLD_CONDITION)) {
        out.name = out.name.replaceAll(OLD_CONDITION, NEW_CONDITION);
        touched = true;
      }
      if (!(Array.isArray(out.triggers) && out.triggers.length) && String(out.name ?? '').trim()) {
        out.triggers = [String(out.name).trim()];
        touched = true;
      }
      if (!out.id || used.has(out.id)) {
        let id;
        do { id = foundry.utils.randomID(); } while (reserved.has(id));
        reserved.add(id);
        out.id = id;
        touched = true;
      }
      used.add(out.id);
      if (touched) changed += 1;
      return out;
    });
    return { ...tab, entries };
  });
  return { tabs: next, changed };
}

/**
 * Copy each layer stack stored under an older key to its current key, then delete every key the Studio can't reach.
 * An older key starts with the class name as a slug and names the entry by name, by index or by ID; a current key
 * holds the class name and the entry ID as code points. A key more than one entry could claim is left where it is.
 */
function planCompositions(comp, oldTabs, newTabs, update) {
  const slug = (value, fallback) => studio.slugifyName(value || fallback) || fallback;
  const codePoints = text => Array.from(String(text), char => char.codePointAt(0).toString(16)).join('-');
  const types = studio.typeOptions().map(option => option.value);
  const rows = [];
  oldTabs.forEach((tab, tabIndex) => {
    const oldClass = slug(tab?.name, 'Default');
    for (const type of types) {
      rows.push({
        sources: [oldClass + '__none__' + slug(type, 'default')],
        target: studio.compKey({ classKey: tab?.name, type })
      });
    }
    (tab?.entries ?? []).forEach((entry, entryIndex) => {
      const target = newTabs[tabIndex].entries[entryIndex];
      for (const type of types) {
        const typeSlug = slug(type, 'default');
        rows.push({
          sources: [
            entry?.id ? oldClass + '__id-' + codePoints(entry.id) + '__' + typeSlug : null,
            oldClass + '__' + slug(entry?.name, 'entry') + '__' + typeSlug,
            oldClass + '__e' + entryIndex + '__' + typeSlug
          ].filter(Boolean),
          target: studio.compKey({ classKey: tab?.name, entryId: target.id, type })
        });
      }
    });
  });
  const owners = new Map();
  for (const row of rows) {
    for (const key of row.sources) {
      if (!owners.has(key)) owners.set(key, new Set());
      owners.get(key).add(row.target);
    }
  }
  const ambiguous = new Set([...owners].filter(([key, targets]) => comp[key] && targets.size > 1).map(([key]) => key));
  let moved = 0;
  for (const row of rows) {
    if (comp[row.target]) continue;
    const source = row.sources.find(key => key !== row.target && comp[key] && !ambiguous.has(key));
    if (!source) continue;
    update['flags.' + STUDIO + '.tokenComp.' + row.target] = foundry.utils.deepClone(comp[source]);
    moved += 1;
  }
  const valid = new Set(['default'].map(type => studio.compKey({ classKey: 'Default', type })));
  for (const tab of newTabs) {
    for (const type of types) {
      valid.add(studio.compKey({ classKey: tab.name, type }));
      for (const entry of tab.entries ?? []) valid.add(studio.compKey({ classKey: tab.name, entryId: entry.id, type }));
    }
  }
  let deleted = 0;
  for (const key of Object.keys(comp)) {
    if (valid.has(key) || ambiguous.has(key)) continue;
    update['flags.' + STUDIO + '.tokenComp.' + key] = DELETE();
    deleted += 1;
  }
  return { moved, deleted, ambiguous: [...ambiguous] };
}

/** Remove the version stamp from every animation and effect payload in a value, in place. */
function stripVersions(value) {
  if (Array.isArray(value)) value.forEach(stripVersions);
  else if (value && typeof value === 'object') {
    if (Array.isArray(value.steps)) delete value.version;
    Object.values(value).forEach(stripVersions);
  }
  return value;
}

/**
 * Bring each custom status (an apply status step with preset custom) in a list of effect entries to the current
 * shape with normalizeCustomStatus, in place, including steps inside if steps, and say whether any changed. The
 * step's own duration moves into the data and is removed; a step with no readable data is left for the effect editor
 * to report.
 */
function normalizeCustomStatuses(entries) {
  if (!customStatus || !Array.isArray(entries)) return false;
  let changed = false;
  const visit = steps => {
    for (const step of Array.isArray(steps) ? steps : []) {
      if (foundry.utils.getType(step) !== 'Object') continue;
      if (step.kind === 'applyEffect' && step.preset === 'custom'
        && foundry.utils.getType(step.customData) === 'Object') {
        const next = customStatus.normalizeCustomStatus(step.customData, step);
        if (Object.hasOwn(step, 'durationPhases') || JSON.stringify(next) !== JSON.stringify(step.customData)) {
          changed = true;
        }
        step.customData = next;
        delete step.durationPhases;
      }
      if (step.kind === 'if') {
        visit(step.then);
        visit(step.else);
      }
    }
  };
  for (const entry of entries) visit(entry?.action?.steps);
  return changed;
}

/** Whether any custom status in an item's effects is still in an older shape. The item is not changed. */
function customStatusesStale(item) {
  const effects = item._source.system?.effects;
  return Array.isArray(effects) && normalizeCustomStatuses(foundry.utils.deepClone(effects));
}

/**
 * Bring each Remove status step in a list of effect entries to the current shape with normalizeRemoveStatus, in
 * place, including steps inside if steps, and say whether any changed. A step that had both a status name and a
 * dispel box keeps only its name, and its place (label, trigger and step number) is added to `ambiguous` when given.
 */
function normalizeRemoveStatuses(entries, label = '', ambiguous = null) {
  if (!removeStatus || !Array.isArray(entries)) return false;
  let changed = false;
  const visit = (steps, place) => {
    if (!Array.isArray(steps)) return;
    steps.forEach((step, index) => {
      if (foundry.utils.getType(step) !== 'Object') return;
      const here = place + 'step ' + (index + 1);
      if (step.kind === 'removeEffect') {
        const result = removeStatus.normalizeRemoveStatus(step);
        if (result.changed) {
          steps[index] = result.step;
          changed = true;
        }
        if (result.ambiguous) ambiguous?.push(here);
      }
      if (step.kind === 'if') {
        visit(step.then, here + ', then ');
        visit(step.else, here + ', else ');
      }
    });
  };
  entries.forEach((entry, index) => {
    const trigger = entry?.trigger || entry?.name || 'effect ' + (index + 1);
    visit(entry?.action?.steps, label + ' / ' + trigger + ' / ');
  });
  return changed;
}

/** Whether any Remove status step in an item's effects is still in an older shape. The item is not changed. */
function removeStatusesStale(item) {
  const effects = item._source.system?.effects;
  return Array.isArray(effects) && normalizeRemoveStatuses(foundry.utils.deepClone(effects));
}

/**
 * Bring each Restore actions step in a list of effect entries to the current shape with normalizeRestoreAction, in
 * place, including steps inside if steps, and say whether any changed. A step that gave back the whole turn now
 * gives back the standard action, the bonus action and movement.
 */
function normalizeRestoreActions(entries) {
  if (!restoreAction || !Array.isArray(entries)) return false;
  let changed = false;
  const visit = steps => {
    if (!Array.isArray(steps)) return;
    steps.forEach((step, index) => {
      if (foundry.utils.getType(step) !== 'Object') return;
      if (step.kind === 'restoreAction') {
        const result = restoreAction.normalizeRestoreAction(step);
        if (result.changed) {
          steps[index] = result.step;
          changed = true;
        }
      }
      if (step.kind === 'if') {
        visit(step.then);
        visit(step.else);
      }
    });
  };
  for (const entry of entries) visit(entry?.action?.steps);
  return changed;
}

/** Whether any Restore actions step in an item's effects still gives back the whole turn. The item is not changed. */
function restoreActionsStale(item) {
  const effects = item._source.system?.effects;
  return Array.isArray(effects) && normalizeRestoreActions(foundry.utils.deepClone(effects));
}

/** Each item's animations and effects under their old names, read raw, since loading drops keys the schema no longer has. */
async function storedPayloads(operation) {
  const rows = await Item.database.get(Item, {
    query: {}, index: true, indexFields: ['_id', 'system.animV2', 'system.effectsV2'], ...operation
  });
  return new Map(rows.map(row => [row._id, row.system ?? {}]));
}

/**
 * Rewrite an item's system data from its schema, which drops every key the schema no longer has, after moving its
 * animations and effects off their old names, bringing its custom statuses, Remove status steps and Restore actions
 * steps to the current shape and removing the version stamps. Also clear its dead flags. An item that already has an animation slot or
 * effects under the new name as well as the old one is left untouched and reported, so neither version is lost.
 */
function planItem(item, stored = {}, label = '') {
  const system = item.toObject().system;
  const slots = ['attack', 'critical', 'activation'];
  const clash = (system.anim && slots.some(slot => system.anim[slot] && stored.animV2?.[slot]))
    || (system.effects?.length && stored.effectsV2?.length);
  if (clash) {
    summary.conflicts.push(label + ' / ' + item.name);
    return null;
  }
  if (system.anim) for (const slot of slots) system.anim[slot] ??= stored.animV2?.[slot] ?? null;
  if (Array.isArray(system.effects) && stored.effectsV2?.length) system.effects = stored.effectsV2;
  const customChanged = normalizeCustomStatuses(system.effects);
  const ambiguous = [];
  const removeChanged = normalizeRemoveStatuses(system.effects, label + ' / ' + item.name, ambiguous);
  const restoreChanged = normalizeRestoreActions(system.effects);
  const clean = new item.system.constructor(system).toObject();
  stripVersions(clean.anim);
  stripVersions(clean.effects);
  const update = { _id: item.id, system: ForcedReplacement.create(clean) };
  if (customChanged) customRewrites.add(update);
  if (removeChanged) removeRewrites.set(update, ambiguous);
  if (restoreChanged) restoreRewrites.add(update);
  for (const path of DEAD_ITEM_FLAGS) {
    if (foundry.utils.getProperty(item.flags ?? {}, path) !== undefined) update['flags.' + path] = DELETE();
  }
  if (item.flags?.[STUDIO]?.pixelArt !== undefined) {
    if (item.flags[STUDIO].pixelArt && item.flags['emblem-rpg']?.pixelArt === undefined) update['flags.emblem-rpg.pixelArt'] = true;
    update['flags.' + STUDIO + '.pixelArt'] = DELETE();
  }
  return update;
}

/**
 * Whether an item still holds animations or effects under their old names, a retired flag, or a custom status,
 * Remove status step or Restore actions step in an older shape.
 */
function needsMigration(item, stored = {}) {
  return stored.animV2 !== undefined || stored.effectsV2 !== undefined
    || DEAD_ITEM_FLAGS.some(path => foundry.utils.getProperty(item.flags ?? {}, path) !== undefined)
    || item.flags?.[STUDIO]?.pixelArt !== undefined
    || customStatusesStale(item)
    || removeStatusesStale(item)
    || restoreActionsStale(item);
}

/**
 * Migrate a set of items in batches. With staleOnly, an item is rewritten only when needsMigration finds old data
 * in it, so a module compendium that is already current is left byte for byte as it shipped.
 */
async function migrateItems(items, label, { parent = null, pack = null, source = {}, staleOnly = false } = {}) {
  const present = items.filter(Boolean);
  if (!present.length) return;
  let stored;
  try {
    stored = await storedPayloads(source);
  } catch (error) {
    summary.errors.push(label + ': the stored items could not be read, so they were left as they are. ' + error.message);
    return;
  }
  const updates = [];
  for (const item of present) {
    try {
      if (staleOnly && !needsMigration(item, stored.get(item.id))) continue;
      const update = planItem(item, stored.get(item.id), label);
      if (update) updates.push(update);
    } catch (error) {
      summary.errors.push(label + ' / ' + item.name + ': ' + (error?.message ?? error));
    }
  }
  for (let start = 0; start < updates.length; start += 100) {
    const batch = updates.slice(start, start + 100);
    const customCount = batch.filter(update => customRewrites.has(update)).length;
    const removeUpdates = batch.filter(update => removeRewrites.has(update));
    const restoreCount = batch.filter(update => restoreRewrites.has(update)).length;
    try {
      if (parent) await parent.updateEmbeddedDocuments('Item', batch, itemWriteOptions());
      else await Item.updateDocuments(batch, itemWriteOptions(pack));
      summary.items += batch.length;
      summary.customStatuses += customCount;
      summary.removeStatuses += removeUpdates.length;
      summary.restoreActions += restoreCount;
      for (const update of removeUpdates) ambiguousSteps.push(...removeRewrites.get(update));
    } catch (error) {
      summary.errors.push(label + ': ' + error.message);
    }
  }
}

/** Each Actor's stored art, read raw, since loading drops the Default token variants the schema no longer has. */
async function storedArt(operation = {}) {
  const rows = await Actor.database.get(Actor, { query: {}, index: true, indexFields: ['_id', 'system.art'], ...operation });
  return new Map(rows.map(row => [row._id, row.system?.art]));
}

/**
 * Remove the version stamps from an Armament's animations and effects, and bring its custom statuses, Remove status
 * steps and Restore actions steps up to date.
 */
async function migrateArmament(actor, label) {
  const system = actor.toObject().system;
  if (system.anim === undefined || system.effects === undefined) return;
  const before = JSON.stringify([system.anim, system.effects]);
  stripVersions(system.anim);
  stripVersions(system.effects);
  const customChanged = normalizeCustomStatuses(system.effects);
  const ambiguous = [];
  const removeChanged = normalizeRemoveStatuses(system.effects, label, ambiguous);
  const restoreChanged = normalizeRestoreActions(system.effects);
  if (JSON.stringify([system.anim, system.effects]) === before) return;
  try {
    await actor.update({ 'system.anim': ForcedReplacement.create(system.anim), 'system.effects': system.effects }, { diff: false });
    summary.actors += 1;
    if (customChanged) summary.customStatuses += 1;
    if (removeChanged) summary.removeStatuses += 1;
    if (restoreChanged) summary.restoreActions += 1;
    ambiguousSteps.push(...ambiguous);
  } catch (error) {
    summary.errors.push(label + ': ' + error.message);
  }
}

async function migrateUnit(actor, label, rawArt = null) {
  if (actor?.type !== 'Character' && !Array.isArray(actor?.system?.art?.tabs)) return;
  const update = {};
  const oldTabs = foundry.utils.deepClone(actor.system?.art?.tabs ?? []);
  const { tabs, changed } = planTabs(oldTabs);
  if (changed) update['system.art.tabs'] = tabs;
  const comp = actor.getFlag(STUDIO, 'tokenComp');
  if (studio && comp && typeof comp === 'object') {
    const plan = planCompositions(comp, oldTabs, tabs, update);
    for (const key of plan.ambiguous) summary.ambiguous.push(label + ': ' + key);
  }
  for (const group of ['tokens', 'tokenScales', 'tokenOffsetsY']) {
    if (Object.keys(rawArt?.[group] ?? {}).some(slot => VARIANT_SLOTS.includes(slot))) {
      update['system.art.' + group] = ForcedReplacement.create(actor.toObject().system.art[group]);
    }
  }
  if (actor.flags?.['emblem-rpg']?.selectedPassives !== undefined) update['flags.emblem-rpg.selectedPassives'] = DELETE();
  if (actor.flags?.[STUDIO]?.compositionKeyVersion !== undefined) {
    update['flags.' + STUDIO + '.compositionKeyVersion'] = DELETE();
  }
  if (foundry.utils.isEmpty(update)) return;
  try {
    await actor.update(update, { diff: false });
    summary.actors += 1;
  } catch (error) {
    summary.errors.push(label + ': ' + error.message);
  }
}

/** Migrate one unlinked token's own art, armament and items, which live in its ActorDelta. */
async function migrateToken(token, label) {
  const delta = token.delta?._source ?? {};
  const deltaArt = delta.system?.art?.tokens === undefined ? null : (await ActorDelta.database.get(ActorDelta,
    { parentUuid: token.uuid, query: {}, index: true, indexFields: ['system.art'] }))[0]?.system?.art ?? null;
  const holdsArt = delta.system?.art?.tabs !== undefined || delta.flags?.[STUDIO] !== undefined
    || delta.flags?.['emblem-rpg']?.selectedPassives !== undefined || deltaArt !== null;
  if (holdsArt) await migrateUnit(token.actor, label, deltaArt);
  const deltaItems = (token.delta?._source.items ?? []).map(item => token.actor.items.get(item._id));
  if (delta.system?.anim !== undefined || delta.system?.effects !== undefined) {
    await migrateArmament(token.actor, label);
  }
  await migrateItems(deltaItems, label, { parent: token.actor, source: { parentUuid: token.delta.uuid } });
}

/**
 * Migrate one Actor or Item compendium, unlocking it for the writes and locking it again afterwards. Items in a
 * module's compendium are rewritten only when they still hold old data.
 */
async function migratePack(pack) {
  const staleOnly = pack.metadata.packageType !== 'world';
  const wasLocked = pack.locked;
  if (wasLocked) await pack.configure({ locked: false });
  try {
    const documents = await pack.getDocuments();
    if (pack.documentName === 'Item') {
      await migrateItems(documents, pack.title, { pack: pack.collection, source: { pack: pack.collection }, staleOnly });
      return;
    }
    const packArt = await storedArt({ pack: pack.collection });
    for (const actor of documents) {
      const label = pack.title + ' / ' + actor.name;
      await guarded(label, () => migrateUnit(actor, label, packArt.get(actor.id)));
      await guarded(label, () => migrateArmament(actor, label));
      await guarded(label, () => migrateItems(actor.items.contents, label,
        { parent: actor, source: { parentUuid: actor.uuid, pack: pack.collection }, staleOnly }));
    }
  } finally {
    if (wasLocked) await pack.configure({ locked: true });
  }
}

const worldArt = await storedArt().catch(error => {
  summary.errors.push('World actors: their stored art could not be read, so their Default token variants were kept. '
    + error.message);
  return new Map();
});
for (const actor of game.actors) {
  await guarded(actor.name, () => migrateUnit(actor, actor.name, worldArt.get(actor.id)));
  await guarded(actor.name, () => migrateArmament(actor, actor.name));
  await guarded(actor.name, () => migrateItems(actor.items.contents, actor.name,
    { parent: actor, source: { parentUuid: actor.uuid } }));
}
await guarded('World items', () => migrateItems(game.items.contents, 'World items'));

for (const scene of game.scenes) {
  for (const token of scene.tokens) {
    if (token.actorLink || !token.actor) continue;
    const label = scene.name + ' / ' + token.name;
    await guarded(label, () => migrateToken(token, label));
  }
}

for (const pack of game.packs) {
  if (!['Actor', 'Item'].includes(pack.documentName)) continue;
  await guarded(pack.title, () => migratePack(pack));
}

summary.ambiguous.push(...ambiguousSteps.map(place => place + ': Remove status step kept its status name and '
  + 'dropped its dispel box'));
console.group('emblem-rpg | Migrate World Content');
console.log(summary);
console.groupEnd();
if (unattended) return summary;
if (summary.conflicts.length) ui.notifications.warn('Migrate World Content: ' + summary.conflicts.length + ' item(s) have animations or effects under both the old and new names and were left as they are. See the console.');
if (summary.errors.length) ui.notifications.error('Migrate World Content: ' + summary.errors.length + ' failure(s). See the console.');
if (ambiguousSteps.length) {
  ui.notifications.warn('Migrate World Content: ' + ambiguousSteps.length + ' Remove status step(s) named a status and '
    + 'also removed every harmful or beneficial status. They now remove only the named status, so check them: '
    + ambiguousSteps.join('; ') + '.');
}
ui.notifications.info(summary.actors + ' actors and ' + summary.items + ' items updated. Custom statuses were '
  + 'brought up to date on ' + summary.customStatuses + ' of them. Remove status steps were brought up to date on '
  + summary.removeStatuses + ' of them. Restore actions steps were brought up to date on ' + summary.restoreActions
  + ' of them.');
return summary;
